#!/usr/bin/env python3
"""Exact state-level reflection closure for the generic support-seven H6 endpoint.

This verifier is a compact bookkeeping certificate over the exact 14,174-state
H6 universe. CURRENT_HEX is the state-index ledger for the previously certified
4,704-cell endpoint. LATER_HEX is the state-index ledger for the 272 exact
post-order-hull branch exclusions proved by the six committed adaptive/two-face
verifiers through extension4. The ledgers are snapshots of those exact results,
not substitutes for their Fraction-based Farkas checkers.

The new step is purely combinatorial: construct the hull-reflection involution
on the full exact state representation, close the current survivor set under
that involution, and verify that every newly removed state's reflected partner
is one of the 272 already exact-certified exclusions. No floating point
arithmetic or optimization occurs here.
"""
from collections import Counter
from hashlib import sha256
from pathlib import Path
import contextlib
import importlib.util
import io

HERE = Path(__file__).resolve().parent
NSTATE = 14174
CURRENT_SHA256 = "05ce7eed8bd36bef3ecf22480af68c6daa031673194b4da0e6d34aa5abe0a21d"
LATER_SHA256 = "cf97e790c85021c52a350884d01c1a33c07c89ce650e16f88cc544c79d0bdf62"
CURRENT_HEX = ""
LATER_HEX = ""


def decode_ledger(hex_text, expected_sha):
    raw = bytes.fromhex(hex_text)
    assert len(raw) == (NSTATE + 7) // 8
    assert sha256(raw).hexdigest() == expected_sha
    out = set()
    for i in range(NSTATE):
        if raw[i // 8] & (1 << (i % 8)):
            out.add(i)
    for i in range(NSTATE, 8 * len(raw)):
        assert not (raw[i // 8] & (1 << (i % 8)))
    return out


def load_triangle_module():
    path = HERE / "verify_target_c_support7_h6_triangle_simplex_reduction_2026_09_19.py"
    spec = importlib.util.spec_from_file_location("h6_triangle_simplex", path)
    module = importlib.util.module_from_spec(spec)
    with contextlib.redirect_stdout(io.StringIO()):
        spec.loader.exec_module(module)
    return module


def edge(a, b):
    return (a, b) if a < b else (b, a)


RHO = {0: 0, 1: 5, 2: 4, 3: 3, 4: 2, 5: 1, 6: 6, 7: 7}


def state_key(st):
    return (
        st[1],
        tuple(sorted(st[2])),
        tuple(tuple(x) for x in st[3]),
        tuple(st[5]),
        tuple(sorted(st[6].items())),
    )


def reflected_key(st):
    _, graph_type, missing, raws, _chi, pattern, signs = st
    reflected_raws = [None] * 6
    for i in range(6):
        reflected_raws[RHO[i]] = tuple(RHO[v] for v in reversed(raws[i]))
    reflected_missing = tuple(sorted(
        edge(RHO[a], RHO[b]) for a, b in missing
    ))
    reflected_pattern = tuple(sorted(8 - int(p) for p in pattern))
    reflected_signs = tuple(sorted(
        (edge(RHO[a], RHO[b]), s) for (a, b), s in signs.items()
    ))
    return (
        graph_type,
        reflected_missing,
        tuple(reflected_raws),
        reflected_pattern,
        reflected_signs,
    )


def main():
    current = decode_ledger(CURRENT_HEX, CURRENT_SHA256)
    later = decode_ledger(LATER_HEX, LATER_SHA256)
    assert len(current) == 4704
    assert len(later) == 272
    assert current.isdisjoint(later)

    tri = load_triangle_module()
    states = tri.collect_survivors()
    assert len(states) == NSTATE

    current_graph = Counter(states[i][1] for i in current)
    current_pattern = Counter("".join(map(str, states[i][5])) for i in current)
    assert current_graph == Counter({"C7": 3760, "C3+C4": 944})
    assert current_pattern == Counter({
        "145": 4, "156": 16, "235": 642, "236": 1263,
        "237": 16, "245": 471, "256": 1153, "345": 20,
        "346": 478, "347": 4, "356": 637,
    })

    by_key = {state_key(st): i for i, st in enumerate(states)}
    assert len(by_key) == NSTATE
    reflected = []
    for st in states:
        key = reflected_key(st)
        assert key in by_key
        reflected.append(by_key[key])

    assert len(set(reflected)) == NSTATE
    assert all(reflected[reflected[i]] == i for i in range(NSTATE))
    assert all(states[reflected[i]][1] == states[i][1] for i in range(NSTATE))

    reflected_current = {reflected[i] for i in current}
    closure = current & reflected_current
    newly_excluded = current - closure
    assert len(closure) == 4464
    assert len(newly_excluded) == 240

    source_partners = {reflected[i] for i in newly_excluded}
    assert len(source_partners) == 240
    assert source_partners <= later
    assert {reflected[i] for i in closure} == closure

    new_graph = Counter(states[i][1] for i in newly_excluded)
    new_pattern = Counter(
        "".join(map(str, states[i][5])) for i in newly_excluded
    )
    assert new_graph == Counter({"C7": 180, "C3+C4": 60})
    assert new_pattern == Counter({
        "235": 37, "236": 129, "245": 6, "256": 19,
        "345": 4, "346": 13, "356": 32,
    })

    final_graph = Counter(states[i][1] for i in closure)
    final_pattern = Counter("".join(map(str, states[i][5])) for i in closure)
    assert final_graph == Counter({"C7": 3580, "C3+C4": 884})
    assert final_pattern == Counter({
        "145": 4, "156": 16, "235": 605, "236": 1134,
        "237": 16, "245": 465, "256": 1134, "345": 16,
        "346": 465, "347": 4, "356": 605,
    })
    assert sum(final_pattern.values()) == 4464

    print("PASS: exact H6 state-level reflection closure")
    print("current exact endpoint: 4704 = 3760 C7 + 944 C3+C4")
    print("new reflected exact exclusions: 240 = 180 C7 + 60 C3+C4")
    print("new exclusions by ground pattern:", dict(sorted(new_pattern.items())))
    print("remaining explicit endpoint: 4464 = 3580 C7 + 884 C3+C4")
    print("remaining ground patterns:", dict(sorted(final_pattern.items())))


if __name__ == "__main__":
    main()
